def solve(I, res_rule):
    """
    res_rule: 'maj' = most common, 'first' = earliest occurrence, 'maxc' = largest column
    """
    I=[[int(x) for x in r] for r in I]; H,W=len(I),len(I[0]); O=[row[:] for row in I]
    for r in range(H):
        nz=[(c,I[r][c]) for c in range(W) if I[r][c]!=0]
        if not any(v==0 for _,v in nz): continue
        cands=[]
        for P in range(2,W+1):
            cnt=collections.defaultdict(list)
            for c,v in nz: cnt[c%P].append(v)
            ok=all(len(set(s))==1 for s in cnt.values())
            nundef=sum(1 for c in range(W) if I[r][c]==0 and c%P not in cnt)
            if not ok or nundef!=0: continue
            fill=sum(1 for c in range(W) if I[r][c]==0 and c%P in cnt)
            mp={k:int(set(s)[0]) for k,s in cnt.items()}
            # force fillable only where defined by rule: all zeros resolved? use fill>=number of zeros covered... skip details
            # require: filling this P resolves at least max zeros, prefer smallest P with no unresolved zeros
            nfill=max(0,sum(1 for c in range(W) if I[r][c]==0 and c%P in cnt))
            # define P valid iff no zero-left-empty? not necessarily; pick P maximizing fill
            cands.append(((fill,P)))
        cands.sort()           # smaller P first
        if not cands: continue
        _,mL=cands[0]
        cnt=collections.defaultdict(list)
        for c,v in nz: cnt[c%mL].append(v)
        mm={k:set(s) for k,s in cnt.items()}
        if res_rule=='maj':
            mp={k:collections.Counter(s).most_common(1)[0][0] for k,s in cnt.items()}
        elif res_rule=='first':
            mp={k:s[0] for k,s in cnt.items()}
        else:
            mp={k:max(s) for k,s in cnt.items()}
        O[r]=[mp.get(c%mL) if I[r][c]==0 else I[r][c] for c in range(W)]
    return O

