G=load()
def solve(I):
    I=[[int(x) for x in r] for r in I]; H,W=len(I),len(I[0]); O=[row[:] for row in I]
    for r in range(H):
        nz=[(c,I[r][c]) for c in range(W) if I[r][c]!=0]
        if all(I[r][c]!=0 for c in range(W)): continue
        for P in range(2,W+1):
            mm=collections.defaultdict(set)
            for c,v in nz: mm[c%P].add(v)
            if any(len(s)>1 for s in mm.values()): continue
            mp={k:int(list(s)[0]) for k,s in mm.items()}
            # every zero's residue must be defined
            if all(c%P in mp for c,v in enumerate(I[r]) if v==0):
                mL=P; break
        if mL:
            mp={k:int(list(mm[k])) for k in collections.defaultdict(set)} or {}
            mm=collections.defaultdict(set)
            for c,v in nz: mm[c%mL].add(v)
            mp2={k:int(list(s)[0]) for k,s in mm.items()}
            O[r]=[mp2.get(c%mL) if I[r][c]==0 else I[r][c] for c in range(W)]
    return O
